parameters.message:
=<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 0 auto; padding: 20px; }
    h1 { color: #2563eb; border-bottom: 3px solid #2563eb; padding-bottom: 10px; }
    h2 { color: #1e40af; margin-top: 30px; }
    .header { background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%); color: white; padding: 30px; border-radius: 10px; margin-bottom: 30px; }
    .header h1 { color: white; border: none; margin: 0; }
    .content { background: #f8fafc; padding: 25px; border-radius: 10px; }
    .footer { margin-top: 40px; padding: 20px; background: #f1f5f9; border-radius: 10px; text-align: center; }
    .cta-button { display: inline-block; background: #2563eb; color: white; padding: 12px 30px; text-decoration: none; border-radius: 5px; margin-top: 15px; }
    ul, ol { padding-left: 20px; }
    li { margin-bottom: 8px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Your 30-Day Content Strategy</h1>
    <p>Personalized for: {{ $('Webhook').item.json.body.niche }}</p>
  </div>

  <div class="content">
    {{ $json.output[0].content[0].text }}
  </div>

  <div class="footer">
    <p><strong>Ready to execute this strategy?</strong></p>
    <p>Consistency is key - start with Day 1 today!</p>
    <p style="color: #64748b; font-size: 12px; margin-top: 20px;">This strategy was generated based on your inputs: {{ $('Webhook').item.json.body.content_goals }}</p>
  </div>
</body>
</html>
